package studio.jiayu.neoagent;
public class RejectedActionsTest {
 static int n;static void yes(boolean ok,String message){if(!ok)throw new AssertionError(message);n++;}
 public static void main(String[] args){RejectedActions r=new RejectedActions();r.record("scene1","native-node-identity","tap","params","boundary");yes(r.find("scene1","native-node-identity","tap","params")!=null,"unchanged rejected tap retried");yes(r.find("scene1","native-node-identity","purchase_check","params")==null,"alternative tool blocked");yes(r.find("scene1","another-native-node","tap","params")==null,"alternative entry blocked");yes(r.find("scene2","native-node-identity","tap","params")==null,"new screen cannot re-evaluate");yes(r.find("scene1","native-node-identity","tap","new-params")==null,"corrected input blocked");r.record("scene1","native-node-identity","tap","params","new wording");yes(r.entries.size()==1&&r.entries.peek().attempts==2,"duplicate failure not merged");yes(r.entries.peek().reason.equals("boundary"),"original reason lost");for(int i=0;i<15;i++)r.record("scene"+i,"target","tap","params","reason");yes(r.entries.size()==12,"feedback not bounded");r.clear();yes(r.entries.isEmpty(),"old goal failures retained");System.out.println("PASS: "+n+" rejected-action recovery checks");}
}
